#pragma once
#include <vector>
#include <fstream>
#include <map>
#include <algorithm>
#include <string>
#include <cstdint>
#include <stdexcept>
#include <iostream>
#ifndef GERBIL_ROOT
#define GERBIL_ROOT "."
#endif
struct GCase{uint32_t k,ip,n,entries,threshold,unique;std::vector<uint32_t>keys,expected;std::vector<std::string>dna;};
inline std::vector<GCase>load_cases(){std::ifstream f(std::string(GERBIL_ROOT)+"/fixtures.bin",std::ios::binary);if(!f)throw std::runtime_error("missing Gerbil fixture");auto rd=[&](){uint32_t x;f.read((char*)&x,4);if(!f)throw std::runtime_error("truncated Gerbil fixture");return x;};auto n=rd();std::vector<GCase>cs;for(unsigned i=0;i<n;i++){GCase c;c.k=rd();c.ip=rd();c.n=rd();c.entries=rd();c.threshold=rd();c.unique=rd();auto ne=rd(),ndna=rd();c.keys.resize(c.n*c.ip);c.expected.resize(ne);f.read((char*)c.keys.data(),c.keys.size()*4);f.read((char*)c.expected.data(),ne*4);for(unsigned j=0;j<ndna;j++){std::string s(c.k,' ');f.read(&s[0],c.k);c.dna.push_back(s);}if(!f)throw std::runtime_error("bad Gerbil asset");cs.push_back(c);}return cs;}
inline std::vector<uint32_t>canonical_extract(const GCase&c,const std::vector<uint32_t>&table,std::vector<uint32_t>&permutation){std::vector<uint32_t>occupied,empty;for(unsigned i=0;i<c.entries;i++){auto p=table.data()+i*(c.ip+1);if(p[c.ip]){if(p[c.ip]==0xffffffff)throw std::runtime_error("locked counter remains");occupied.push_back(i);}else{for(unsigned j=0;j<c.ip;j++)if(p[j])throw std::runtime_error("discarded nonzero empty payload");empty.push_back(i);}}auto less=[&](uint32_t a,uint32_t b){return std::lexicographical_compare(table.begin()+a*(c.ip+1),table.begin()+a*(c.ip+1)+c.ip,table.begin()+b*(c.ip+1),table.begin()+b*(c.ip+1)+c.ip);};std::sort(occupied.begin(),occupied.end(),less);for(unsigned i=1;i<occupied.size();i++)if(!less(occupied[i-1],occupied[i]))throw std::runtime_error("duplicate occupied key");permutation=occupied;permutation.insert(permutation.end(),empty.begin(),empty.end());auto sortedperm=permutation;std::sort(sortedperm.begin(),sortedperm.end());for(unsigned i=0;i<c.entries;i++)if(sortedperm[i]!=i)throw std::runtime_error("not full bijection");std::vector<uint32_t>out,hist(512,0),selected;for(auto i:permutation){auto p=table.data()+i*(c.ip+1);out.insert(out.end(),p,p+c.ip+1);}for(auto i:occupied){auto p=table.data()+i*(c.ip+1);auto count=p[c.ip];hist[count<512?count:0]++;if(count>=c.threshold)selected.insert(selected.end(),p,p+c.ip+1);}out.insert(out.end(),hist.begin(),hist.end());out.push_back(selected.size()/(c.ip+1));out.insert(out.end(),selected.begin(),selected.end());return out;}
inline bool check_record(const uint64_t*x,size_t n){auto cs=load_cases();std::vector<uint64_t>expected;for(auto&c:cs){expected.insert(expected.end(),c.entries*(c.ip+1),0);expected.insert(expected.end(),c.n*c.ip,0xa5a5a5a5);expected.push_back(0);expected.insert(expected.end(),c.keys.begin(),c.keys.end());}for(auto&c:cs){expected.insert(expected.end(),c.expected.begin(),c.expected.end());expected.insert(expected.end(),c.n*c.ip,0xa5a5a5a5);expected.push_back(0);expected.insert(expected.end(),112,0xa5a5a5a5);expected.insert(expected.end(),2,0xa5a5a5a5a5a5a5a5ull);}if(n!=expected.size()){std::cerr<<"shape "<<n<<" != "<<expected.size()<<"\n";return false;}size_t bad=0;for(size_t i=0;i<n;i++)if(x[i]!=expected[i]){if(bad<8)std::cerr<<"wrong "<<i<<" "<<x[i]<<" != "<<expected[i]<<"\n";bad++;}if(bad)std::cerr<<"total wrong="<<bad<<"\n";return !bad;}
